class WalletModel {
  WalletModel({
    this.journal,
    this.transaction,
  });

  WalletModel.fromJson(dynamic json) {
    if (json['journal'] != null) {
      journal = [];
      json['journal'].forEach((v) {
        journal?.add(JournalModel.fromJson(v));
      });
    }
    if (json['transaction'] != null) {
      transaction = [];
      json['transaction'].forEach((v) {
        transaction?.add(PaymentModel.fromJson(v));
      });
    }
  }

  List<JournalModel>? journal;
  List<PaymentModel>? transaction;

  WalletModel copyWith({
    List<JournalModel>? journal,
    List<PaymentModel>? transaction,
  }) =>
      WalletModel(
        journal: journal ?? this.journal,
        transaction: transaction ?? this.transaction,
      );

  num? get availableMoney => journal
      ?.where((element) => element.journalType == JournalType.cash)
      .first
      .remainsAmount;

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    if (journal != null) {
      map['journal'] = journal?.map((v) => v.toJson()).toList();
    }
    if (transaction != null) {
      map['transaction'] = transaction?.map((v) => v.toJson()).toList();
    }
    return map;
  }
}
